    }

    .filter-pill {
      padding: 8px 16px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-muted);
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 20px;
      transition: all 0.15s;
    }

    .filter-pill:hover {
      border-color: var(--accent);
      color: var(--accent);
    }

    .filter-pill.active {
      background: var(--accent);
      color: #fff;
      border-color: var(--accent);
    }

    .search-wrapper {
      position: relative;
      margin-left: auto;
    }

    .search-icon {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      color: var(--text-muted);
