      border: 1px solid var(--border);
      border-radius: 8px;
      background: var(--card-bg);
      transition: all 0.15s;
    }

    .search-input:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(0, 114, 245, 0.1);
