      letter-spacing: 0.05em;
      color: var(--accent);
      margin-bottom: 10px;
    }

    .article-card h3 {
      font-size: 16px;
      font-weight: 600;
      color: var(--primary);
      margin-bottom: 8px;
      line-height: 1.4;
    }

    .article-card .excerpt {
      font-size: 14px;
      color: var(--text-muted);
      line-height: 1.5;
      margin-bottom: 16px;
