    .btn-primary:hover { opacity: 0.9; }

    .btn-secondary {
      padding: 12px 24px;
      font-size: 14px;
      font-weight: 600;
      color: #fff;
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: 8px;
      transition: background 0.15s;
