    .btn-secondary:hover { background: rgba(255,255,255,0.2); }

    .cta-enterprise {
      background: rgba(255,255,255,0.05);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: 12px;
      padding: 32px;
      text-align: center;
