    .cta-enterprise h3 {
      font-size: 20px;
      font-weight: 700;
      color: #fff;
      margin-bottom: 8px;
    }

    .cta-enterprise p {
      font-size: 14px;
      color: rgba(255,255,255,0.7);
      margin-bottom: 20px;
    }

    /* Footer */
    .footer {
      background: #fff;
      border-top: 1px solid var(--border);
      padding: 64px 24px 32px;
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    .footer-grid {
