      grid-template-columns: repeat(6, 1fr);
      gap: 32px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 16px;
    }

    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .footer-col a {
      font-size: 14px;
      color: var(--text);
      transition: color 0.15s;
    }

    .footer-col a:hover { color: var(--accent); }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 32px;
      border-top: 1px solid var(--border);
    }

    .footer-brand {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 14px;
      font-weight: 600;
      color: var(--text);
    }

    .footer-brand .logo-icon {
      width: 24px;
      height: 24px;
      background: var(--accent);
      border-radius: 5px;
    }

    .footer-status {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      color: var(--text-muted);
    }

    .status-dot {
      width: 8px;
      height: 8px;
      background: #22c55e;
      border-radius: 50%;
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .featured-grid, .latest-grid {
        grid-template-columns: repeat(2, 1fr);
      }
      .stats-bar { grid-template-columns: repeat(3, 1fr); }
      .cta-inner { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 768px) {
      .header-main { gap: 16px; }
      .nav-main { display: none; }
      .search-wrapper { margin-left: 0; width: 100%; }
      .search-input { width: 100%; }
      .hero h1 { font-size: 32px; }
      .filters-wrapper { flex-direction: column; align-items: stretch; }
      .category-filters { overflow-x: auto; flex-wrap: nowrap; padding-bottom: 8px; }
      .featured-grid, .latest-grid { grid-template-columns: 1fr; }
      .stats-bar { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-bottom { flex-direction: column; gap: 16px; }
      .cta-buttons { flex-direction: column; }
      .dropdown-panel.products { width: 90vw; }
    }

    .hidden { display: none !important; }
  </style>
</head>
