<script>
  // Dropdown toggle
  function toggleDropdown(trigger) {
    const navItem = trigger.closest('.nav-item');
    const panel = navItem.querySelector('.dropdown-panel');
    const isOpen = panel.style.opacity === '1';

    // Close all dropdowns first
    document.querySelectorAll('.dropdown-panel').forEach(p => {
      p.style.opacity = '0';
      p.style.visibility = 'hidden';
    });

    if (!isOpen) {
      panel.style.opacity = '1';
      panel.style.visibility = 'visible';
    }
  }

  // Close dropdowns when clicking outside
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.nav-item')) {
      document.querySelectorAll('.dropdown-panel').forEach(p => {
        p.style.opacity = '0';
        p.style.visibility = 'hidden';
      });
    }
  });

  // Category filters
  const categoryFilters = document.getElementById('categoryFilters');
  const searchInput = document.getElementById('searchInput');
  const featuredGrid = document.getElementById('featuredGrid');
  const latestGrid = document.getElementById('latestGrid');
  const noResults = document.getElementById('noResults');
  const showMoreBtn = document.getElementById('showMoreBtn');
  const showMoreWrapper = document.getElementById('showMoreWrapper');
  const moreGrid = document.getElementById('moreGrid');

  let activeCategory = 'all';
  let searchQuery = '';
  let hasShownMore = false;

  // Get all cards (featured + latest)
  function getAllCards() {
    const featuredCards = Array.from(featuredGrid.querySelectorAll('.featured-card'));
    const latestCards = Array.from(latestGrid.querySelectorAll('.article-card'));
    const moreCards = Array.from(moreGrid.querySelectorAll('.article-card'));
    return { featuredCards, latestCards, moreCards };
  }

  function filterCards() {
    const { featuredCards, latestCards } = getAllCards();
    let visibleCount = 0;

    // Filter featured cards (only show if "all" or matches category)
    featuredCards.forEach(card => {
      const cardCategory = card.dataset.category;
      const matchesCategory = activeCategory === 'all' || cardCategory === activeCategory;
      const cardText = card.textContent.toLowerCase();
      const matchesSearch = searchQuery === '' || cardText.includes(searchQuery);

      if (matchesCategory && matchesSearch) {
        card.style.display = '';
        visibleCount++;
      } else {
        card.style.display = 'none';
      }
    });

    // Filter latest cards
    latestCards.forEach(card => {
      const cardCategory = card.dataset.category;
      const matchesCategory = activeCategory === 'all' || cardCategory === activeCategory;
      const cardText = card.textContent.toLowerCase();
      const matchesSearch = searchQuery === '' || cardText.includes(searchQuery);

      if (matchesCategory && matchesSearch) {
        card.style.display = '';
        visibleCount++;
      } else {
        card.style.display = 'none';
      }
    });

    // Filter more cards if shown
    if (hasShownMore) {
      const moreCards = Array.from(moreGrid.querySelectorAll('.article-card'));
      moreCards.forEach(card => {
        const cardCategory = card.dataset.category;
        const matchesCategory = activeCategory === 'all' || cardCategory === activeCategory;
        const cardText = card.textContent.toLowerCase();
        const matchesSearch = searchQuery === '' || cardText.includes(searchQuery);

        if (matchesCategory && matchesSearch) {
          card.style.display = '';
          visibleCount++;
        } else {
          card.style.display = 'none';
        }
      });
    }

    // Show/hide no results
    if (visibleCount === 0) {
      noResults.classList.add('visible');
    } else {
      noResults.classList.remove('visible');
    }

    // Hide show more if filtered
    if (activeCategory !== 'all' || searchQuery !== '') {
      showMoreWrapper.style.display = 'none';
    } else {
      showMoreWrapper.style.display = 'flex';
    }
  }

  // Category filter click
  categoryFilters.addEventListener('click', (e) => {
    if (e.target.classList.contains('filter-pill')) {
      // Update active state
      categoryFilters.querySelectorAll('.filter-pill').forEach(p => p.classList.remove('active'));
      e.target.classList.add('active');

      activeCategory = e.target.dataset.category;
      filterCards();
    }
  });

  // Search input
  searchInput.addEventListener('input', (e) => {
    searchQuery = e.target.value.toLowerCase().trim();
    filterCards();
  });

  // Show more posts
  showMoreBtn.addEventListener('click', () => {
    hasShownMore = true;
    moreGrid.classList.remove('hidden');
    showMoreWrapper.style.display = 'none';
  });
</script>

